const r = await tools.exec_command({
  cmd: "Write-Output '--- REMOTE SKILL TREE ---'
git ls-tree -r origin/main -- .agents .claude agent skills-lock.json
Write-Output "`n--- LOCAL ITEMS ---"
Get-Item -Force .agents,.claude,agent,skills-lock.json | Select-Object FullName,Attributes,LinkType,Target | Format-List
Write-Output "`n--- LOCAL FILE COUNT ---"
(Get-ChildItem -Force -Recurse -File .agents,.claude,agent | Measure-Object).Count
Write-Output "`n--- HASH COMPARISON ---"
$roots = @('.agents','.claude','agent')
$files = foreach ($root in $roots) { Get-ChildItem -Force -Recurse -File $root }
$files += Get-Item skills-lock.json
$rows = foreach ($file in $files) {
  $rel = [System.IO.Path]::GetRelativePath((Get-Location).Path, $file.FullName).Replace('\\','/')
  $localHash = (git hash-object --no-filters -- $file.FullName).Trim()
  $remoteHash = (git rev-parse "origin/main:$rel" 2>$null).Trim()
  [pscustomobject]@{ Path=$rel; Match=($localHash -eq $remoteHash); Local=$localHash; Remote=$remoteHash }
}
$rows | Where-Object { -not $_.Match } | Format-Table -AutoSize
Write-Output "Compared $($rows.Count) files; mismatches: $(($rows | Where-Object { -not $_.Match }).Count)"",
  workdir: "C:\Users\User\Documents\ChatGPT\cogniframe",
  yield_time_ms: 10000,
  max_output_tokens: 30000
});
text(r.output);

