    _apply_coverage(state, director, strategist, SCHEMA)
    assert state["resolved_notes"][0]["beat"] == "TRACTION"
    assert state["resolved_notes"][0]["closed_by"] == "take_traction"
    assert state["resolved_notes"][0]["shot"]["line"] == "Say a number"

