    def run(*args: object, **kwargs: object) -> Completed:
        nonlocal calls
        calls += 1
        result = Completed()
        if calls == 2:
            result.stderr = "mean_volume: -100.0 dB\nmax_volume: -100.0 dB\n"
        return result

    monkeypatch.setattr("palantum.orchestrator.subprocess.run", run)
    result = _audio_check(
        tmp_path / "final.mp4",
        [
            {"start": 0.0, "end": 1.0},
            {"start": 1.0, "end": 2.0},
        ],
    )
