    director = {
        "beats": [
            {
                "id": beat["id"],
                "status": "covered" if beat["id"] == "TRACTION" else "missing",
                "source": "take_traction" if beat["id"] == "TRACTION" else None,
                "range": [0, 1] if beat["id"] == "TRACTION" else None,
                "reason": "measured",
