import { AbsoluteFill, useCurrentFrame, spring, interpolate, useVideoConfig } from 'remotion'
export const BarChartReveal: React.FC<{
  variant?: string
  textColor?: string
  title?: string
  barLabels?: string
  barValues?: string
}> = ({
  variant = 'default',
  textColor = '#171717',
  title = 'Revenue Growth',
  barLabels = 'Q1,Q2,Q3,Q4',
  barValues = '65,78,92,100',
}) => {
  const frame = useCurrentFrame()
  const { fps } = useVideoConfig()
  const s = {
    fontFamily: 'system-ui, sans-serif',
    fontWeight: 600,
    letterSpacing: '-0.02em',
    borderRadius: 12,
    shadow: undefined,
    borderWidth: 1,
    borderColor: '#e5e5e5',
    card: { borderRadius: 12, border: '1px solid #e5e5e5', boxShadow: undefined, background: undefined },
    text: { fontWeight: 600, letterSpacing: '-0.02em', fontFamily: 'system-ui, sans-serif' },
  }
  const isMono = false

  const titleS = spring({ frame, fps, config: { stiffness: 200, damping: 20 } })
  const labelArr = barLabels.split(',').map((s) => s.trim())
  const valueArr = barValues.split(',').map((s) => parseFloat(s.trim()) || 0)
  const palette = ['#d4d4d4', '#a3a3a3', '#525252', textColor]
  const bars = labelArr.slice(0, 4).map((label, i) => ({
    label,
    value: valueArr[i] ?? 0,
