import { AbsoluteFill, useCurrentFrame, spring, interpolate, useVideoConfig } from 'remotion'
export const BarChartReveal: React.FC<{
  variant?: string
  textColor?: string
  title?: string
  barLabels?: string
  barValues?: string
}> = ({
  variant = 'default',
  textColor = '#171717',
  title = 'Revenue Growth',
  barLabels = 'Q1,Q2,Q3,Q4',
  barValues = '65,78,92,100',
}) => {
  const frame = useCurrentFrame()
  const { fps } = useVideoConfig()
  const s = {
    fontFamily: 'system-ui, sans-serif',
    fontWeight: 600,
    letterSpacing: '-0.02em',
    borderRadius: 12,
    shadow: undefined,
    borderWidth: 1,
    borderColor: '#e5e5e5',
    card: { borderRadius: 12, border: '1px solid #e5e5e5', boxShadow: undefined, background: undefined },
    text: { fontWeight: 600, letterSpacing: '-0.02em', fontFamily: 'system-ui, sans-serif' },
  }
  const isMono = false

  const titleS = spring({ frame, fps, config: { stiffness: 200, damping: 20 } })
  const labelArr = barLabels.split(',').map((s) => s.trim())
  const valueArr = barValues.split(',').map((s) => parseFloat(s.trim()) || 0)
  const palette = ['#d4d4d4', '#a3a3a3', '#525252', textColor]
  const bars = labelArr.slice(0, 4).map((label, i) => ({
    label,
    value: valueArr[i] ?? 0,
    color: palette[i] ?? textColor,
  }))

  return (
    <AbsoluteFill style={{ justifyContent: 'center', alignItems: 'center', backgroundColor: '#fff' }}>
      <div style={{ width: 480 }}>
        <h2 style={{
          fontSize: isMono ? 24 : 28, fontWeight: s.fontWeight, color: textColor, marginBottom: 32,
          opacity: titleS, fontFamily: s.fontFamily, letterSpacing: s.letterSpacing,
          textTransform: isMono ? 'uppercase' as const : 'none' as const,
        }}>{title}</h2>

        <div style={{ display: 'flex', alignItems: 'flex-end', gap: 20, height: 200 }}>
          {bars.map((bar, i) => {
            const delay = 10 + i * 8
            const sp = spring({ frame: frame - delay, fps, config: { stiffness: 150, damping: 14 } })
            const height = interpolate(sp, [0, 1], [0, bar.value * 1.8])

            return (
              <div key={i} style={{ flex: 1, display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 8 }}>
                <div style={{
                  fontSize: 14, fontWeight: s.fontWeight, color: textColor, fontFamily: s.fontFamily,
                  opacity: sp,
                }}>{bar.value}%</div>
                <div style={{
                  width: '100%', height, backgroundColor: bar.color, borderRadius: '6px 6px 0 0',
                }} />
                <div style={{
                  fontSize: 13, color: '#a3a3a3', fontFamily: s.fontFamily,
                  opacity: sp,
                }}>{bar.label}</div>
              </div>
            )
          })}
        </div>
      </div>
    </AbsoluteFill>
  )
}
