import { AbsoluteFill, useCurrentFrame, spring, interpolate, useVideoConfig } from 'remotion'
export const BrandStatement: React.FC<{
  variant?: string
  statement?: string
  highlight?: string
  bgColor?: string
  textColor?: string
}> = ({
  variant = 'default',
  statement = 'We build products that people actually love to use',
  highlight = 'actually love',
  bgColor = '#B39DDB',
  textColor = '#4A148C',
}) => {
  const frame = useCurrentFrame()
  const { fps } = useVideoConfig()
  const s = {
    fontFamily: 'system-ui, sans-serif',
    fontWeight: 600,
    letterSpacing: '-0.02em',
    borderRadius: 12,
    shadow: undefined,
    borderWidth: 1,
    borderColor: '#e5e5e5',
