    text: { fontWeight: 600, letterSpacing: '-0.02em', fontFamily: 'system-ui, sans-serif' },
  }
// Background fade in
  const bgOpacity = spring({ frame, fps, config: { stiffness: 100, damping: 20 } })

  // Split statement into words
  const words = statement.split(' ')
  const highlightWords = highlight.toLowerCase().split(' ')

  return (
    <AbsoluteFill>
      {/* Background */}
      <AbsoluteFill style={{
        backgroundColor: bgColor,
        opacity: bgOpacity,
      }} />

      {/* Centered text */}
      <AbsoluteFill style={{
        justifyContent: 'center',
        alignItems: 'center',
        padding: '0 360px',
      }}>
        <div style={{
          maxWidth: 1200,
          fontSize: 56,
          fontWeight: 700,
          lineHeight: 1.15,
          color: textColor,
          fontFamily: s.fontFamily,
          letterSpacing: s.letterSpacing,
          textAlign: 'center',
          display: 'flex',
          flexWrap: 'wrap',
          justifyContent: 'center',
          gap: '0 18px',
        }}>
          {words.map((word, i) => {
            const wordSpring = spring({ frame: frame - 6 - i * 4, fps, config: { stiffness: 140, damping: 16 } })
            const wordOpacity = interpolate(wordSpring, [0, 1], [0, 1])
            const wordY = interpolate(wordSpring, [0, 1], [20, 0])
            const isHighlighted = highlightWords.includes(word.toLowerCase())

            // Highlighted words get a scale bounce
            const bounceScale = isHighlighted
              ? interpolate(wordSpring, [0, 0.6, 1], [0.85, 1.08, 1])
              : 1

            return (
              <span key={i} style={{
                display: 'inline-block',
                opacity: wordOpacity,
                transform: `translateY(${wordY}px) scale(${bounceScale})`,
                color: isHighlighted ? '#ffffff' : textColor,
                fontWeight: isHighlighted ? 800 : 700,
